 function npcText(e){if(e.id==='mara')return game.quest===0?`“${game.name}, thank the old roads you're here. The beacon at Fenwatch died three nights ago. When its light failed, something answered from the marsh. Toren heard the bell. Sella found strange ash on the bank. Will you help us?”`:game.quest===1?`“Toren's memory is sound, and Sella found the same blue ash. The old shrine is where the first beacon stood. Find out what has woken there.”`:game.quest===2?`“The lantern is in your hands now. Whatever waits on that hill, do not let the flame go out.”`:`“You brought back the dawn, ${game.name}. Hearthmere will remember.”`;
 if(e.id==='toren')return game.quest===0?`“Three nights, near midnight. I heard the Fenwatch bell ring once—though the rope was cut years ago. A cold blue light moved along the water. Not a boat. Not anything living.”`:game.quest===1?`“That ash Sella found? Same color as the lantern glass at the old drowned shrine. Keep to the ridge; the fen has a way of borrowing familiar voices.”`:`“Keep your ears open out there. Silence is the fen's favorite trick.”`;
 if(e.id==='sella')return game.quest===0?`“I found this on the eastern bank. Blue ash that won't wash off. I can brew you a warding draught—if you bring me three moon-reeds from the marsh.”`:game.quest===1?`“The ash is older than the kingdom. Take this tonic; you'll need a clear head near the shrine.”`:`“A little nettle, a little moon-reed, and a lot of luck. That's medicine in the fen.”`;
 return game.quest===0?`“Rumors are my trade, and lately the best ones all smell of wet stone. A light under the water, a bell with no rope, and a shrine nobody can find twice.”`:`“For a few coins I can point you toward the safer paths. Or the interesting ones.”`}
-function dialogChoices(e){if(e.id==='mara')return game.quest===0?[{label:'“I will find out what happened.”',action:'quest'}]:game.quest===1?[{label:'“I’m heading to the drowned shrine.”',action:'close'}]:game.quest===2?[{label:'“I’ll bring the lantern home.”',action:'close'}]:[{label:'“The beacon is safe. For now.”',action:'close'},{label:'“Any work around the village?”',action:'work'}];if(e.id==='toren')return [{label:'“Tell me about the fen.”',action:'clue'},{label:'“Thank you. I’ll be careful.”',action:'close'}];if(e.id==='sella')return game.quest===0?[{label:'“I’ll look for moon-reeds.”',action:'clue'},{label:'“Could I buy a potion? (8 gold)”',action:'buy'},{label:'“Goodbye.”',action:'close'}]:[{label:'“Thanks for the tonic.”',action:'clue'},{label:'“Could I buy a potion? (8 gold)”',action:'buy'},{label:'“Goodbye.”',action:'close'}];return [{label:'“What are people saying?”',action:'clue'},{label:'“Show me what you have. (8 gold)”',action:'buy'},{label:'“Farewell.”',action:'close'}]}
+function dialogChoices(e){if(e.id==='mara')return game.quest===0?[{label:'“I will find out what happened.”',action:'quest'}]:game.quest===1?[{label:'“I’m heading to the drowned shrine.”',action:'close'}]:game.quest===2?[{label:'“I’ll bring the lantern home.”',action:'close'}]:game.quest===3?[{label:'“The lantern is safe. I brought it home.”',action:'finish'}]:[{label:'“The beacon is safe. For now.”',action:'close'},{label:'“Any work around the village?”',action:'work'}];if(e.id==='toren')return [{label:'“Tell me about the fen.”',action:'clue'},{label:'“Thank you. I’ll be careful.”',action:'close'}];if(e.id==='sella')return game.quest===0?[{label:'“I’ll look for moon-reeds.”',action:'clue'},{label:'“Could I buy a potion? (8 gold)”',action:'buy'},{label:'“Goodbye.”',action:'close'}]:[{label:'“Thanks for the tonic.”',action:'clue'},{label:'“Could I buy a potion? (8 gold)”',action:'buy'},{label:'“Goodbye.”',action:'close'}];return [{label:'“What are people saying?”',action:'clue'},{label:'“Show me what you have. (8 gold)”',action:'buy'},{label:'“Farewell.”',action:'close'}]}
 function chooseDialogue(i){let e=dialogNpc;if(!e)return;let c=dialogChoices(e)[i];if(!c)return;switch(c.action){case'quest':game.quest=1;game.clues=Math.max(game.clues,1);setQuest('A light in the fen','Mara asked you to learn what silenced the beacon. The ferryman heard its bell; the apothecary found blue ash.','Gather the villagers’ accounts. Speak with Toren and Sella.');game.rep++;renderDialogue(e,'“Bless you. Toren is by the east road, Sella keeps the little shop. Ask both of them what they saw.”');toast('Quest started: A light in the fen');break;case'clue':if(e.id==='toren'&&game.quest===1){game.clues=Math.max(game.clues,2);advanceClues()}else if(e.id==='sella'&&game.quest===1){game.clues=Math.max(game.clues,3);game.potions++;advanceClues()}else if(e.id==='bryn'){game.gold=Math.max(0,game.gold-2);renderDialogue(e,'“They say the lantern was made to hold a star. They also say the old shrine is full of things that hate the light. That part I believe.”');toast('You learned a rumor. (-2 gold)')}else{renderDialogue(e,e.id==='toren'?'“My ferry days are behind me. But the water remembers every crossing.”':'“Moon-reeds grow where the moon touches still water. Look for pale flowers near the fen.”')}updateStats();save();break;case'buy':if(game.gold>=8){game.gold-=8;game.potions++;updateStats();renderDialogue(e,'“A good choice. Keep the stopper tight; marsh air ruins everything.”');save()}else renderDialogue(e,'“Come back when your purse is heavier, friend.”');break;case'work':closeDialogue();toast('No other work today. The fen is trouble enough.');break;default:closeDialogue()} }
 function advanceClues(){if(game.clues>=3){game.quest=2;setQuest('The drowned shrine','The villagers’ stories point to a shrine hidden beyond the eastern fen. Something waits where the first beacon stood.','Travel east into the Old Fen and find the drowned shrine.');renderDialogue(dialogNpc,'“Three signs, one truth. The lantern fell silent at the shrine. Go east, past the reeds. And take this tonic—it may be all that stands between you and the dark.”');game.xp+=35;toast('Clues gathered. New destination: The Old Fen.');updateStats()}else{renderDialogue(dialogNpc,'“That is one piece of it. Ask the others; their stories fit together like a broken map.”');toast('Clue discovered.')}save()}
 function setQuest(title,copy,obj){document.getElementById('questtitle').textContent=title;document.getElementById('questcopy').textContent=copy;document.getElementById('objective').textContent=obj;document.getElementById('questcount').innerHTML=`◈ &nbsp;${Math.min(game.clues,3)} / 3 clues gathered`}
 function attack(e){if(!e||e.dead)return;game.target=null;let damage=14+(game.cls.name==='Rogue'?5:0);e.hp-=damage;toast(`${e.name} takes ${damage} damage.`);if(e.hp<=0){e.dead=true;game.kills++;game.xp+=28;game.gold+=5;toast(`${e.name} defeated · +28 XP · +5 gold`);if(game.quest===2&&e.id==='wisp'){game.quest=3;setQuest('The last lantern','A blue flame flickers inside the ancient shrine. Bring its light back to Hearthmere.','Return to Mara in Hearthmere Crossing.');toast('Quest updated: Carry the lantern home.')}updateStats();save()}else{let retaliation=Math.max(4,Math.floor(Math.random()*9)+4);game.hp=Math.max(0,game.hp-retaliation);if(game.hp===0){game.hp=Math.ceil(game.cls.hp*.55);game.x=35;game.y=35;game.gold=Math.max(0,game.gold-4);toast('You awaken in Hearthmere. The fen took 4 gold.')}updateStats()}drawMini()}

