 function draw(){ctx.clearRect(0,0,vw,vh);let grad=ctx.createLinearGradient(0,0,0,vh);grad.addColorStop(0,'#1d2b21');grad.addColorStop(1,'#243328');ctx.fillStyle=grad;ctx.fillRect(0,0,vw,vh);drawGround();let objects=decor.map(d=>({sort:d.x+d.y,draw:()=>drawDecor(d)}));for(let e of entities)objects.push({sort:e.x+e.y,draw:()=>drawEntity(e)});objects.push({sort:game.x+game.y+.02,draw:drawPlayer});objects.sort((a,b)=>a.sort-b.sort);objects.forEach(o=>o.draw());if(game.started){let n=nearestEntity();document.querySelector('.hint').innerHTML=n?`<strong>E</strong> speak to ${n.name.split(' ')[0]} &nbsp;·&nbsp; <strong>Click</strong> travel<br><strong>1–4</strong> abilities`:`<strong>W A S D</strong> move &nbsp;·&nbsp; <strong>Click</strong> travel<br><strong>E</strong> interact &nbsp;·&nbsp; <strong>1–4</strong> abilities`}requestAnimationFrame(draw)}
 function drawMini(){if(!mctx)return;let s=mini.width/W;mctx.clearRect(0,0,mini.width,mini.height);for(let y=0;y<H;y++)for(let x=0;x<W;x++){let t=tile(x,y);mctx.fillStyle=t===2?'#526e6b':t===3?'#8a8060':t===4?'#525a43':t===1?'#63714d':'#435941';mctx.fillRect(x*s,y*s,s+.2,s+.2)}for(let e of entities)if(!e.dead){mctx.fillStyle=e.kind==='enemy'?'#ca7661':'#edc879';mctx.beginPath();mctx.arc((e.x+.5)*s,(e.y+.5)*s,2.4,0,7);mctx.fill()}mctx.fillStyle='#f3e7c7';mctx.beginPath();mctx.arc(game.x*s,game.y*s,3,0,7);mctx.fill();mctx.strokeStyle='#e1ca8c44';mctx.strokeRect((game.x-7)*s,(game.y-7)*s,14*s,14*s)}
 function loop(t){let dt=Math.min(.05,(t-last)/1000||0);last=t;if(game.started&&!document.querySelector('.overlay:not(.hidden)')){let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(dx||dy){let l=Math.hypot(dx,dy);movePlayer(dx/l*dt*5.2,dy/l*dt*5.2)}if(game.target){let d=Math.hypot(game.target.x-game.x,game.target.y-game.y);if(d<.3)game.target=null;else movePlayer((game.target.x-game.x)/d*dt*4,(game.target.y-game.y)/d*dt*4)}game.time+=dt;if(game.time>90){game.time=0;entities.filter(e=>e.kind==='enemy'&&!e.dead).forEach(e=>{if(Math.hypot(e.x-game.x,e.y-game.y)<6){e.x+=Math.sign(game.x-e.x)*.02;e.y+=Math.sign(game.y-e.y)*.02}})}cam.x+=(game.x-cam.x)*Math.min(1,dt*4);cam.y+=(game.y-cam.y)*Math.min(1,dt*4);drawMini()}requestAnimationFrame(loop)}
 function movePlayer(dx,dy){let nx=Math.max(1,Math.min(W-2,game.x+dx)),ny=Math.max(1,Math.min(H-2,game.y+dy));if(tile(nx,ny)!==2){game.x=nx;game.y=ny;let loc=Math.hypot(nx-35,ny-35)<10?'Hearthmere Crossing':ny>47?'Mosswood Verge':nx>46?'The Old Fen':nx<17?'Westreach Road':'Greenward';document.getElementById('location').textContent=loc;drawMini();checkAreas()}}
-function checkAreas(){if(game.x>46&&game.y<28&&game.quest<2){game.quest=2;setQuest('The Old Fen','The beacon hill lies ahead. Search the drowned shrine for the source of the blue flame.','Find the drowned shrine in the Old Fen.');toast('The air chills as you enter the Old Fen.')}if(game.x<16&&game.y<16&&game.rep>0)toastOnce('westreach','The old road leads toward the kingdom’s border.')}
+function checkAreas(){if(game.x>46&&game.y<28&&game.quest>=2){toastOnce('oldfen','The air chills as you enter the Old Fen. The drowned shrine lies beyond the reeds.')}if(game.x<16&&game.y<16&&game.rep>0)toastOnce('westreach','The old road leads toward the kingdom’s border.')}
 let seenToast={};function toastOnce(id,msg){if(!seenToast[id]){seenToast[id]=1;toast(msg)}}
 canvas.addEventListener('click',ev=>{if(!game.started)return;let r=canvas.getBoundingClientRect(),pos=unproject(ev.clientX-r.left,ev.clientY-r.top);let e=entities.find(e=>!e.dead&&Math.hypot(e.x-pos.x,e.y-pos.y)<1.2);if(e){game.target={x:e.x,y:e.y};if(Math.hypot(e.x-game.x,e.y-game.y)<2.2){if(e.kind==='enemy')attack(e);else openDialogue(e)}return}if(Math.hypot(pos.x-game.x,pos.y-game.y)<.8)return;game.target={x:pos.x,y:pos.y};});
 addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(e.repeat)return;keys[k]=true;if(k==='e'){if(!document.getElementById('dialog').classList.contains('hidden'))closeDialogue();else interact()}if(k==='escape'){closeDialogue();closePanel()}if(k>='1'&&k<='4')useSkill(+k);if(k==='m')openPanel('map');if(k==='i')openPanel('inventory')});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
 document.querySelectorAll('.mobile-controls button').forEach(b=>{let k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();keys[k]=true});['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,()=>keys[k]=false))});

