function openPanel(type){let p=document.getElementById('panel'),title=document.getElementById('paneltitle'),tag=document.getElementById('paneltag'),content=document.getElementById('panelcontent');p.classList.remove('hidden');if(type==='inventory'){title.textContent='Inventory';tag.textContent='Wayfarer’s pack';content.innerHTML=`<div class="tabs"><button class="tab active">Pack</button><button class="tab" onclick="toast('Equipment: ${game.cls.name} gear equipped.')">Equipment</button></div><p>Useful things collected on the road. Gold: <b style="color:#e4bb70">${game.gold} ✦</b> &nbsp; Potions: <b>${game.potions}</b></p><div class="inventory-grid">${[...game.items,...Array(game.potions).fill('Healing potion'),'Moon-reed','Old lantern',...Array(10).fill('')].slice(0,20).map(it=>`<button class="slot" title="${it||'Empty slot'}" onclick="${it==='Healing potion'?'useSkill(4)':`toast('${it||'Empty slot'}')`}">${it==='Healing potion'?'⚗':it==='Weathered sword'?'⚔':it==='Fenward map'?'🗺':it==='Moon-reed'?'🌾':it==='Old lantern'?'🏮':it?'✧':''}<small>${it?it.split(' ')[0]:''}</small></button>`).join('')}</div><div class="divider"></div><p class="notice">Your pack is light. The road is long.</p>`}else if(type==='character'){title.textContent='Character';tag.textContent='The one who walks the old roads';content.innerHTML=`<div class="speaker"><div class="avatar">${game.face}</div><div><h2>${game.name}</h2><small>${game.origin[0].toUpperCase()+game.origin.slice(1)} of the ${game.cls.name} · Level ${game.level}</small></div></div><div class="divider"></div><div class="status"><span class="chip">❤️ ${game.cls.hp} vitality</span><span class="chip">✧ ${game.cls.mp} focus</span><span class="chip">⚔ ${game.cls.name==='Rogue'?'19':'14'} attack</span><span class="chip">✦ ${game.gold} gold</span></div><p>${game.cls.desc} You have defeated ${game.kills} foes and earned the trust of ${game.rep} villagers.</p><div class="field"><label>Change appearance</label><select onchange="game.face=this.value;document.getElementById('face').textContent=this.value;save()"><option value="${game.face}">Current appearance</option><option>🧙</option><option>🧝</option><option>🛡️</option><option>🏹</option></select></div><div class="modalfoot"><button class="secondary" onclick="makeClasses();document.getElementById('panel').classList.add('hidden');document.getElementById('create').classList.remove('hidden')">Choose a different class</button></div>`}else{title.textContent='Ashenvale';tag.textContent='The known world';content.innerHTML=`<p>From Hearthmere’s warm lanterns to the drowned Fenwatch shrine, the old roads cross a land waking from a long sleep.</p><div style="position:relative;width:min(100%,500px);aspect-ratio:1;margin:14px auto;border:1px solid #c9a45f55;border-radius:8px;overflow:hidden;background:#293b2b"><canvas id="bigmap" style="position:absolute;inset:0;width:100%;height:100%"></canvas></div><div class="status"><span class="chip">● You are here</span><span class="chip" style="color:#e99b80">● Hostile creature</span><span class="chip" style="color:#efd18c">● Traveler</span></div><p class="notice">Click the map to set a destination. Roads are not always the safest way.</p>`;setTimeout(drawBigMap,10)} }
function drawBigMap(){let c=document.getElementById('bigmap');if(!c)return;c.width=500;c.height=500;let x=c.getContext('2d'),s=500/W;for(let y=0;y<H;y++)for(let xx=0;xx<W;xx++){let t=tile(xx,y);x.fillStyle=t===2?'#486460':t===3?'#8a8060':t===4?'#515941':t===1?'#60704c':'#465d43';x.fillRect(xx*s,y*s,s+.2,s+.2)}for(let d of decor){if(d.type==='house'||d.type==='shop'||d.type==='well'){x.fillStyle='#b49a67';x.fillRect(d.x*s-3,d.y*s-3,6,6)}}for(let e of entities)if(!e.dead){x.fillStyle=e.kind==='enemy'?'#d27863':'#e9cc84';x.beginPath();x.arc(e.x*s,e.y*s,5,0,7);x.fill()}x.fillStyle='#fff3c1';x.beginPath();x.arc(game.x*s,game.y*s,6,0,7);x.fill();c.onclick=ev=>{let r=c.getBoundingClientRect();game.target={x:(ev.clientX-r.left)/r.width*W,y:(ev.clientY-r.top)/r.height*H};closePanel();toast('Destination marked.')};}
function closePanel(){document.getElementById('panel').classList.add('hidden')}
function finishQuest(){game.quest=4;game.xp+=100;game.gold+=35;game.rep++;game.items.push('Dawn lantern');setQuest('The last lantern','The Fenwatch beacon burns again. But beyond the hills, a second light answers—far to the north.','Your story continues beyond Hearthmere.');updateStats();toast('Quest complete · +100 XP · +35 gold');renderDialogue(dialogNpc,'“The light is home.” Mara’s eyes glisten in its warm glow. “You have given us more than a beacon, Aster. You gave us a reason to stay.” For the first time in three nights, the bells of Hearthmere ring.');save();}
function toggleSound(){sound=!sound;document.getElementById('soundicon').textContent=sound?'♪':'♫';toast(sound?'The night sounds return.':'Ambient sound muted.');if(sound&&window.AudioContext){try{let ac=new AudioContext(),o=ac.createOscillator(),g=ac.createGain();o.frequency.value=196;g.gain.value=.025;o.connect(g);g.connect(ac.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+1.1);o.stop(ac.currentTime+1.2)}catch(e){}}}
function save(){try{let data={...game,cls:game.cls.name};localStorage.setItem('ashenvale-save',JSON.stringify(data))}catch(e){}}
function loadSave(){try{let s=JSON.parse(localStorage.getItem('ashenvale-save')||'null');if(!s||!s.started)return;game={...game,...s,cls:classes.find(c=>c.name===s.cls)||classes[0]};game.started=true;game.target=null;if(game.quest>0){document.getElementById('create').classList.add('hidden');document.getElementById('playername').textContent=game.name;document.getElementById('classlabel').textContent=game.cls.name;document.getElementById('face').textContent=game.face;setQuest(game.quest===4?'The last lantern':game.quest>=2?'The drowned shrine':'A light in the fen',game.quest===4?'The Fenwatch beacon burns again. But beyond the hills, a second light answers—far to the north.':'The old beacon has gone dark. Ask the folk of Hearthmere what they saw in the marsh.',game.quest===4?'Your story continues beyond Hearthmere.':game.quest>=2?'Travel east into the Old Fen and find the drowned shrine.':'Gather the villagers’ accounts. Speak with Toren and Sella.');cam.x=game.x;cam.y=game.y;updateStats()}}catch(e){}}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.getElementById('create').classList.add('hidden')}});
// Quest choices are deliberately reactive: NPCs remember what you have learned.
const originalChoose=chooseDialogue;chooseDialogue=function(i){let e=dialogNpc;if(e&&e.id==='mara'&&game.quest===3&&i===0){finishQuest();return}return originalChoose(i)};
loadSave();requestAnimationFrame(loop);requestAnimationFrame(draw);
</script></body></html>

