function advance(){if(g.clues>=3){g.quest=2;setQuest('The drowned shrine','The villagers’ stories point to a shrine hidden beyond the eastern fen. Something waits where the first beacon stood.','Travel east into the Old Fen and find the drowned shrine.');g.xp+=35;dialogRender(dialogNpc,'“Three signs, one truth. The lantern fell silent at the shrine. Go east, past the reeds. Take this tonic—it may be all that stands between you and the dark.”');toast('Clues gathered. New destination: The Old Fen.');stats()}else{dialogRender(dialogNpc,'“That is one piece of it. Ask the others; their stories fit together like a broken map.”');toast('Clue discovered.')}save()}function setQuest(a,b,c){document.getElementById('qtitle').textContent=a;document.getElementById('qcopy').textContent=b;document.getElementById('objective').textContent=c;document.getElementById('clues').textContent=`◈  ${Math.min(g.clues,3)} / 3 clues gathered`}
function stats(){let maxhp=g.cls.hp+(g.level-1)*12,maxmp=g.cls.mp+(g.level-1)*8;g.hp=Math.max(0,Math.min(maxhp,g.hp));g.mp=Math.max(0,Math.min(maxmp,g.mp));document.getElementById('hpbar').style.width=(g.hp/maxhp*100)+'%';document.getElementById('hptext').textContent=`${Math.ceil(g.hp)} / ${maxhp}`;document.getElementById('mpbar').style.width=(g.mp/maxmp*100)+'%';document.getElementById('mptext').textContent=`${Math.floor(g.mp)} / ${maxmp}`;document.getElementById('xpbar').style.width=(g.xp%100)+'%';document.getElementById('xptext').textContent=`${g.xp%100} / 100`;document.getElementById('level').textContent=g.level;document.getElementById('clues').textContent=`◈  ${Math.min(g.clues,3)} / 3 clues gathered`;drawMini()}
function toast(s){let el=document.getElementById('toast');el.textContent=s;el.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>el.classList.remove('show'),2600)}
function save(){if(!g.started)return;try{localStorage.setItem('ashenvale-save',JSON.stringify({g:{...g,cls:g.cls.name},entities:entities.map(e=>({id:e.id,hp:e.hp,dead:e.dead})),questText:[document.getElementById('qtitle').textContent,document.getElementById('qcopy').textContent,document.getElementById('objective').textContent]}))}catch(e){}}
function load(){try{let s=JSON.parse(localStorage.getItem('ashenvale-save')||'null');if(!s||!s.g)return false;let old=s.g,cls=classes.find(c=>c.name===old.cls)||classes[0];g={...g,...old,cls,started:true};entities.forEach(e=>{let v=(s.entities||[]).find(x=>x.id===e.id);if(v){if(typeof v.hp==='number')e.hp=v.hp;e.dead=!!v.dead}});document.getElementById('create').classList.add('hidden');document.getElementById('pname').textContent=g.name;document.getElementById('classname').textContent=cls.name;document.getElementById('face').textContent=g.face;document.getElementById('hero').value=g.name;document.getElementById('origin').value=g.origin;let q=s.questText||[];if(q.length===3)setQuest(...q);else if(g.quest===1)setQuest('A light in the fen','Mara asked you to learn what silenced the beacon.','Gather the villagers’ accounts. Speak with Toren and Sella.');else if(g.quest===2)setQuest('The drowned shrine','Find the drowned shrine beyond the eastern fen.','Travel east into the Old Fen and defeat the Fen wisp.');else if(g.quest===3)setQuest('Bring the lantern home','The Fen wisp is gone, and the beacon’s heart is yours.','Return to Mara in Hearthmere.');else if(g.quest>=4)setQuest('The Last Lantern','The beacon shines again over Hearthmere.','The fen is quiet—for now.');stats();return true}catch(e){return false}}
function gainXP(n){g.xp+=n;while(g.xp>=100){g.xp-=100;g.level++;g.hp+=18;g.mp+=12;toast(`Level ${g.level}! Your strength grows.`)}stats()}
function nearestEnemy(range=2.2){let best=null,d0=range;for(let e of entities)if(e.kind==='enemy'&&!e.dead){let d=Math.hypot(e.x-g.x,e.y-g.y);if(d<d0){d0=d;best=e}}return best}
function attack(e){if(!g.started||e.dead)return;if(Math.hypot(e.x-g.x,e.y-g.y)>2.25){g.target={x:e.x,y:e.y};toast('Move closer to attack.');return}hurtEnemy(e,11+Math.floor(g.level*2)+(g.origin==='dwarf'?2:0));g.lastCombat=Date.now();if(!e.dead){let now=Date.now();if(!e.lastHit||now-e.lastHit>850){e.lastHit=now;let dmg=e.id==='wisp'?8:6;g.hp=Math.max(0,g.hp-dmg);toast(`${e.name} strikes for ${dmg}.`);stats();if(g.hp<=0)respawn()}}save()}
function hurtEnemy(e,n){e.hp=Math.max(0,e.hp-n);if(e.hp===0){e.dead=true;g.kills++;g.gold+=e.id==='wisp'?35:10;gainXP(e.id==='wisp'?70:32);toast(`${e.name} defeated · +${e.id==='wisp'?70:32} XP`);if(e.id==='wisp'&&g.quest===2){g.quest=3;g.items.push('Beacon-heart lantern');setQuest('Bring the lantern home','The Fen wisp is gone, and the beacon’s heart is yours.','Return to Mara in Hearthmere.');g.potions++;toast('Quest updated: Return the lantern to Mara.')}}else{toast(`${e.name} · ${e.hp} vitality`);stats()}drawMini();save()}
function skill(n){if(!g.started)return;if(n===4){if(g.potions<1){toast('You have no healing potions.');return}let max=g.cls.hp+(g.level-1)*12;if(g.hp>=max){toast('Your vitality is already full.');return}g.potions--;g.hp=Math.min(max,g.hp+45);stats();toast('You drink a healing potion.');save();return}if(n===3){let cost=12;if(g.mp<cost){toast('Not enough focus.');return}g.mp-=cost;let max=g.cls.hp+(g.level-1)*12;g.hp=Math.min(max,g.hp+28+(g.level*3));stats();toast('Mend restores your vitality.');save();return}let e=nearestEnemy(n===2?4.7:2.25);if(!e){toast(n===2?'No enemy within spell range.':'No enemy close enough to strike.');return}if(n===1){attack(e);return}let cost=18;if(g.mp<cost){toast('Not enough focus.');return}g.mp-=cost;let bonus=['Arcanist','Druid','Templar'].includes(g.cls.name)?8:0;hurtEnemy(e,20+g.level*3+bonus);stats();if(!e.dead&&Math.hypot(e.x-g.x,e.y-g.y)<2.4){g.hp=Math.max(0,g.hp-6);stats();if(g.hp<=0)respawn()}save()}
function respawn(){g.hp=Math.ceil((g.cls.hp+(g.level-1)*12)*.55);g.mp=Math.ceil((g.cls.mp+(g.level-1)*8)*.5);g.x=35;g.y=35;g.target=null;area();stats();toast('You awaken at Hearthmere. Your lost gold remains lost.');save()}
function finishQuest(){if(g.quest!==3)return;g.quest=4;g.gold+=100;g.rep+=5;g.items.push('Hearthmere’s seal');gainXP(100);setQuest('The Last Lantern','The beacon shines again over Hearthmere. The villagers have a future, and the road is open.','Main story complete. Explore Ashenvale, grow stronger, and help its people.');dialogRender(dialogNpc,'“Then the light has found its way home. Take this seal, and know Hearthmere will always open its doors to you.”');toast('Chapter I complete · 100 gold · Hearthmere’s seal');save()}
function openPanel(type){if(!g.started){toast('Begin your journey first.');return}let panel=document.getElementById('panel'),title=document.getElementById('paneltitle'),tag=document.getElementById('paneltag'),body=document.getElementById('panelcontent');panel.classList.remove('hidden');let esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));if(type==='character'){tag.textContent='Adventurer’s record';title.textContent=g.name;body.innerHTML=`<div class="copy"><b>${esc(g.cls.name)}</b> · ${esc(g.origin[0].toUpperCase()+g.origin.slice(1))} · Level ${g.level}<br>${esc(g.cls.desc)}</div><div class="divider"></div><div class="copy">Vitality <b>${Math.ceil(g.hp)} / ${g.cls.hp+(g.level-1)*12}</b> · Focus <b>${Math.floor(g.mp)} / ${g.cls.mp+(g.level-1)*8}</b><br>Experience <b>${g.xp} / 100</b> · Enemies defeated <b>${g.kills}</b><br>Gold <b>${g.gold}</b> · Village standing <b>${g.rep}</b></div><div class="divider"></div><div class="copy">${esc(g.cls.name==='Ranger'?'Quick ranged strikes deal extra damage.':g.cls.name==='Warden'?'A hardy guardian with stronger healing.':g.cls.name==='Arcanist'?'Arcane burst deals bonus damage.':'Your training shapes how you face the wilds.')}</div>`}else if(type==='inventory'){tag.textContent='Pack & provisions';title.textContent='Inventory';body.innerHTML=`<div class="copy"><b>Provisions</b><br>Healing potions: ${g.potions}<br>Gold crowns: ${g.gold}</div><div class="divider"></div><div class="copy"><b>Possessions</b><br>${g.items.length?g.items.map(x=>'• '+esc(x)).join('<br>'):'Your pack is empty.'}</div><div class="divider"></div><button class="choice" onclick="skill(4);openPanel('inventory')">Drink healing potion</button>`}else{tag.textContent='Roads of Westreach';title.textContent='Ashenvale';body.innerHTML=`<div class="copy">The known country, and the paths still open to you. Choose a destination to set out; click any clear ground to travel freely.</div><div class="divider"></div><div class="choices"><button class="choice" onclick="travelTo(35,35)">✦ Hearthmere Crossing <small>Village · Mara, Toren, Sella</small></button><button class="choice" onclick="travelTo(25,51)">♧ Mosswood Verge <small>Wild country · Mossback wolf</small></button><button class="choice" onclick="travelTo(51,25)">☾ The Old Fen <small>Marshland · Fen wisp</small></button><button class="choice" onclick="travelTo(55,45)">⚑ Westreach Road <small>Outlaw trail · Fen bandit</small></button></div><div class="divider"></div><canvas id="bigmap" width="360" height="250" style="width:100%;max-height:250px;border:1px solid #d9b56b55;border-radius:8px"></canvas>`;setTimeout(()=>drawBigMap(),0)} }
function drawBigMap(){let el=document.getElementById('bigmap');if(!el)return;let c=el.getContext('2d'),s=el.width/W;c.fillStyle='#19241b';c.fillRect(0,0,el.width,el.height);for(let y=0;y<H;y++)for(let x=0;x<W;x++){let t=terrain(x,y);c.fillStyle=t===2?'#526e6b':t===3?'#8a8060':t===4?'#525a43':t===1?'#63714d':'#435941';c.fillRect(x*s,y*s,s+.3,s+.3)}for(let e of entities)if(!e.dead){c.fillStyle=e.kind==='enemy'?'#ca7661':'#edc879';c.beginPath();c.arc((e.x+.5)*s,(e.y+.5)*s,2.4,0,7);c.fill()}c.fillStyle='#fff0c8';c.beginPath();c.arc(g.x*s,g.y*s,4,0,7);c.fill()}
function travelTo(x,y){closePanel();g.target={x,y};toast('Destination marked. Follow the path.');save()}
function closePanel(){document.getElementById('panel').classList.add('hidden')}
let soundOn=false;function soundToggle(){soundOn=!soundOn;toast(soundOn?'The forest stirs. (Sound enabled)':'Sound muted.');if(soundOn){try{let a=new AudioContext(),o=a.createOscillator(),v=a.createGain();o.frequency.value=196;v.gain.value=.025;o.connect(v);v.connect(a.destination);o.start();o.stop(a.currentTime+.12);o.onended=()=>a.close()}catch(e){}}}
function closeTalk(){document.getElementById('dialog').classList.add('hidden');dialogNpc=null}

